#define ITERATIONS 100
#define ESCAPE_RADIUS 2.

vec2 ref[ITERATIONS];
int refMaxIter;

vec2 compmul(vec2 a, vec2 b) {
    return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x);
}

void setRef(vec2 pos) {
    vec2 z = vec2(0., 0.);
    vec2 c = pos;
    for (int i = 0; i < ITERATIONS; i++) {
        z = compmul(z, z) + c;
        ref[i] = z;

        if (length(z) > ESCAPE_RADIUS * ESCAPE_RADIUS) {
            refMaxIter = i;
            return;
        }
    }

    refMaxIter = ITERATIONS;
}

float getRatio(vec2 dc) {
    vec2 dz = vec2(0., 0.);
    int n = 0;
    int m = 0;
    while (n < ITERATIONS) {
        dz = 2. * compmul(dz, ref[m]) + compmul(dz, dz) + dc;
        m++;
        vec2 z = ref[m] + dz;
        float lengthz = length(z);
        if (lengthz > ESCAPE_RADIUS * ESCAPE_RADIUS) {
            break;
        }
        if (lengthz < length(dz)) {
            dz = z;
            m = 0;
        }
        n++;
    }

    return n == ITERATIONS ? 0. : float(n) / float(ITERATIONS);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 state = texelFetch(iChannel0, ivec2(0., 0.), 0);
    vec2 offset = state.xy;
    float zoom = state.z;

    setRef(offset);

    vec2 uv = fragCoord / iResolution.xy - vec2(.5, .5);
    uv.x *= iResolution.x / iResolution.y;

    float t = getRatio(uv / zoom);
    t = mod(t * 10., 1.);
    fragColor = vec4(t, t, t, 1.);
}

#define ZOOM_CHANGE 2.
#define ZOOM_MIN .01

#define KEY_ZOOM_IN ivec2(87, 0)
#define KEY_ZOOM_OUT ivec2(83, 0)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (fragCoord.x >= 1. || fragCoord.y >= 1.)
        discard;

    // (pos.x, pos.y, zoom, _)
    vec4 state = texelFetch(iChannel0, ivec2(0, 0), 0);
    if (iFrame == 0)
        state = vec4(0., 0., .5, 0.);

    float dzoom = 1.;
    if (texelFetch(iChannel1, KEY_ZOOM_IN, 0).x > 0.)
        dzoom = pow(ZOOM_CHANGE, iTimeDelta);
    if (texelFetch(iChannel1, KEY_ZOOM_OUT, 0).x > 0.)
        dzoom = pow(1. / ZOOM_CHANGE, iTimeDelta);

    if (dzoom != 1.) {
        vec2 uv = iMouse.xy / iResolution.xy;
        vec2 pos = (uv - vec2(.5, .5)) * 2.;
        pos.x *= iResolution.x / iResolution.y;
        pos = pos / state.z + state.xy;
        state.xy = pos + (state.xy - pos) / dzoom;
        state.z *= dzoom;
    }
    if (state.z < ZOOM_MIN)
        state.z = ZOOM_MIN;

    fragColor = state;
}
